{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    for s in segments:
        missing = [k for k in ('name','importance','minimum','capacity') if k not in s]
        if missing:
            raise ValueError(f'Missing fields: {missing}')
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        raise ValueError('Budget out of feasible range')
    alloc = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    cap_left = [s['capacity'] - alloc[i] for i, s in enumerate(segments)]
    while remaining > 0:
        best_idx = -1
        best_num = None
        best_den = None
        for i, s in enumerate(segments):
            if cap_left[i] > 0:
                num = s['importance']
                den = alloc[i] + 1
                if best_idx == -1:
                    best_idx = i
                    best_num = num
                    best_den = den
                else:
                    if num * best_den > best_num * den:
                        best_idx = i
                        best_num = num
                        best_den = den
                    elif num * best_den == best_num * den and i < best_idx:
                        best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        cap_left[best_idx] -= 1
        remaining -= 1
    allocations = {s['name']: alloc[i] for i, s in enumerate(segments)}
    names = [s['name'] for s in segments]
    total_allocated = sum(alloc)
    return {'allocations': allocations, 'names': names, 'total_allocated': total_allocated}
